mapper.select:
select * from walk_step_daily
where member_id = #{memberId}
  and activity_id = #{activityId}
  and date_format(record_date, '%Y-%m-%d') = #{recordDate}

select d.* from walk_step_daily d
inner join walk_member m on d.member_id = m.member_id
where d.activity_id = #{activityId}
  and (m.abnormal_flag is null or m.abnormal_flag != '1')
  and date_format(d.record_date, '%Y-%m-%d') = #{recordDate}
order by d.effective_steps desc

mapper.update:
update walk_step_daily
set is_locked = 'Y', update_time = sysdate()
where activity_id = #{activityId}
  and record_date  <=  #{recordDate}
  and is_locked = 'N'

mapper.select:
select * from walk_step_daily
where member_id = #{memberId}
  and activity_id = #{activityId}
  and is_settled = 'N'
  and record_date  >=  #{activityStart}
  and record_date  <  #{beforeDate}
order by record_date asc

mapper.update:
update walk_step_daily
set is_settled = 'Y', update_time = sysdate()
where member_id = #{memberId}
  and activity_id = #{activityId}
  and date_format(record_date, '%Y-%m-%d') = #{recordDate}
